selector_to_html = {"a[href=\"#pyskyfire-regen-thrust-chamber-thrustchamber\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.thrust_chamber.ThrustChamber<a class=\"headerlink\" href=\"#pyskyfire-regen-thrust-chamber-thrustchamber\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.build_channel_angular_widths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.build_channel_angular_widths\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_channel_angular_widths</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Compute wedge angle (theta) arrays used by cross-section analytics.</p><p>Priority:</p></dd>", "a[href=\"FilmCooling.html#pyskyfire.regen.thrust_chamber.FilmCooling\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.FilmCooling\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.thrust_chamber.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FilmCooling</span></span></dt><dd><p>User-facing film cooling inputs attached to a ThrustChamber.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber._with_keep_out_breakpoints\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber._with_keep_out_breakpoints\">\n<span class=\"sig-name descname\"><span class=\"pre\">_with_keep_out_breakpoints</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x_domain</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Put a station on every corner of a keep-out\u2019s width law.</p><p>Channel widths are interpolated between stations, so a keep-out edge\nbetween two of them would be smeared over the whole interval, or\nmissed if it is shorter. The nearest station is moved onto a corner\nwhen it is within a quarter spacing, so the grid stays even; otherwise\none is added.</p></dd>", "a[href=\"../outer_wall/OuterWall.html#pyskyfire.regen.outer_wall.OuterWall\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.outer_wall.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OuterWall</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">envelope</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">equivalent</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Outer radius of a channelled wall against axial station.</p><p class=\"rubric\">Notes</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_circuit\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_circuit\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_circuit()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_chamber\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_chamber\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_chamber()</span></code></a> rather than\ndirectly, unless the wall is being stated by hand for a part pyskyfire did\nnot resolve.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.build_physical_channel_paths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.build_physical_channel_paths\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_physical_channel_paths</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Resolve section anchors, lobe sizes and centroid paths together.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.install_heat_exchanger\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.install_heat_exchanger\">\n<span class=\"sig-name descname\"><span class=\"pre\">install_heat_exchanger</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exchanger</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">position</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">(0.0,</span> <span class=\"pre\">0.0,</span> <span class=\"pre\">0.0)</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">coefficient</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Place an exchanger against the prescribed gas and report its volume.</p><p>Returns a ChamberInstallation with <code class=\"docutils literal notranslate\"><span class=\"pre\">solve</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">volume_change</span></code>.\nThe chamber temperature, chemistry, contour and gas flow remain prescribed.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.blocked_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.blocked_angle\">\n<span class=\"sig-name descname\"><span class=\"pre\">blocked_angle</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Angle of the channel layer kept clear by keep-outs at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> [rad].</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.outer_wall\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.outer_wall\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">outer_wall</span></span></dt><dd><p>Cold-side envelope of the channelled wall.</p><p>The counterpart to <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">contour</span></code>: where that one is the face the hot\ngas sees, this is the outermost surface the channels and their walls\nreach, which is what anything wrapped around the chamber has to sit\nagainst. Measured on first use and then kept, since it follows from\ngeometry that is already resolved.</p><p>See <a class=\"reference internal\" href=\"../outer_wall/OuterWall.html#pyskyfire.regen.outer_wall.OuterWall\" title=\"pyskyfire.regen.outer_wall.OuterWall\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">OuterWall</span></code></a> for the difference\nbetween its <code class=\"docutils literal notranslate\"><span class=\"pre\">envelope</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">equivalent</span></code> radii.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.build_reference_paths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.build_reference_paths\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_reference_paths</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Build the ideal-contour winding on a shared integration grid.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber._resolve_signed_fraction_to_x\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber._resolve_signed_fraction_to_x\">\n<span class=\"sig-name descname\"><span class=\"pre\">_resolve_signed_fraction_to_x</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">f</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.build_circuit_x_domain\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.build_circuit_x_domain\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_circuit_x_domain</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Convert each circuit\u2019s fractional span into an x-grid whose size\nscales with the fraction of the overall contour length covered.\nUses at least 3 nodes per circuit.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.__getstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.__getstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__getstate__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Leave the derived outer wall out; it rebuilds on demand.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.thrust_chamber.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ThrustChamber</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">contour</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cooling_circuits</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">combustion_transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">optimal_values</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">K_factor</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.3</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_nodes</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">50</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_gas_corr</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_cold_corr</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">compute_gas</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_cooling</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"FilmCooling.html#pyskyfire.regen.thrust_chamber.FilmCooling\" title=\"pyskyfire.regen.thrust_chamber.FilmCooling\"><span class=\"pre\">FilmCooling</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">keep_outs</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Simulation-only thrust-chamber assembly.</p><p class=\"rubric\">Notes</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.coolant_volume\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.coolant_volume\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">coolant_volume</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Wetted coolant volume of every cooling circuit combined [m\u00b3].</p><p>See <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">CoolingCircuit.compute_volume()</span></code> for what one circuit\u2019s\n<code class=\"docutils literal notranslate\"><span class=\"pre\">volume</span></code> covers. Circuits that overlap axially, such as an RL10-style\nhalf pass and full pass, each contribute their own channels.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.number_of_channels\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.number_of_channels\">\n<span class=\"sig-name descname\"><span class=\"pre\">number_of_channels</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">occluding_only</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the total number of active channels at position <cite>x</cite>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.ThrustChamber.build_channel_heights\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.ThrustChamber.build_channel_heights\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_channel_heights</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Evaluate the per-circuit height law h(x) on each circuit domain.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
